def min_cost(n, m, k):
    if k == 0 or k == n * m:
        return 0

    # Use dynamic programming with memoization
    from functools import lru_cache

    @lru_cache(maxsize=None)
    def dp(r, c, needed):
        if needed == 0:
            return 0
        if needed == r * c:
            return 0

        min_cost = float('inf')

        # Try all possible horizontal breaks
        for i in range(1, r):
            # Break into (i, c) and (r-i, c)
            cost = c * c  # Cost of horizontal break (length c)
            # Try taking the top part (i, c)
            if i * c >= needed:
                cost += dp(i, c, needed)
            else:
                cost += dp(i, c, i * c)  # Take all from top
                cost += dp(r-i, c, needed - i * c)  # Take rest from bottom
            min_cost = min(min_cost, cost)

        # Try all possible vertical breaks
        for j in range(1, c):
            # Break into (r, j) and (r, c-j)
            cost = r * r  # Cost of vertical break (length r)
            # Try taking the left part (r, j)
            if r * j >= needed:
                cost += dp(r, j, needed)
            else:
                cost += dp(r, j, r * j)  # Take all from left
                cost += dp(r, c-j, needed - r * j)  # Take rest from right
            min_cost = min(min_cost, cost)

        return min_cost

    return dp(n, m, k)

